bool CollectPlotTopologyRecord(CvPlot& plot, PlotTopologyRecord& out)
{
    // River crossing count.
    out.riverCrossingCount = static_cast<i32>(plot.getRiverCrossingCount());
    // Area identifier.
    out.area = static_cast<i32>(plot.getArea());
    // Landmass identifier.
    out.landmass = static_cast<i32>(plot.getLandmass());
    // Terrain type.
    out.terrainType = static_cast<i8>(plot.getTerrainType());
    // Flat, hill, mountain, or water plot type.
    out.plotType = static_cast<i8>(plot.getPlotType());
    // Hill flag.
    out.hills = (plot.isHills()) ? 1 : 0;
    // Mountain flag.
    out.mountain = (plot.isMountain()) ? 1 : 0;
    // Water flag.
    out.water = (plot.isWater()) ? 1 : 0;
    // Deep-water flag.
    out.deepWater = (plot.isDeepWater()) ? 1 : 0;
    // Lake flag.
    out.lake = (plot.isLake()) ? 1 : 0;
    // Coastal-land flag.
    out.coastalLand = (plot.isCoastalLand()) ? 1 : 0;
    // River flag.
    out.river = (plot.isRiver()) ? 1 : 0;
    // Per-direction river-crossing flags.
    for (int index = 0; index < 1; ++index) {
        out.riverCrossing[index] = 0;
    }
    if ((NUM_DIRECTION_TYPES) > VoxRlDirectionCapacity) {
        return false;
    }
    for (int index = 0; index < (NUM_DIRECTION_TYPES); ++index) {
        if (plot.isRiverCrossing(static_cast<DirectionTypes>(index))) {
            out.riverCrossing[index / 8] = static_cast<u8>(out.riverCrossing[index / 8] | (1 << (index % 8)));
        }
    }
    // Northeast river flow.
    out.northEastRiver = (plot.isNEOfRiver()) ? 1 : 0;
    // West river flow.
    out.westRiver = (plot.isWOfRiver()) ? 1 : 0;
    // Northwest river flow.
    out.northWestRiver = (plot.isNWOfRiver()) ? 1 : 0;
    // Native return type is char.
    out.continentType = static_cast<i8>(plot.GetContinentType());
    // Lowercase native accessor.
    out.roughGround = (plot.isRoughGround()) ? 1 : 0;
    return true;
}

bool CollectPlotDynamicRecord(CvPlot& plot, PlotDynamicRecord& out)
{
    // Effective working-city identity after the native override.
    out.effectiveOwningCityId = static_cast<i32>(plot.getEffectiveOwningCity() ? plot.getEffectiveOwningCity()->GetID() : -1);
    // Improvement type.
    out.improvementType = static_cast<i32>(plot.getImprovementType());
    // Resource type using native defaults.
    out.resourceType = static_cast<i32>(plot.getResourceType());
    // Recon count.
    out.reconCount = static_cast<i32>(plot.getReconCount());
    // Extra path movement cost.
    out.extraMovePathCost = static_cast<i32>(plot.getExtraMovePathCost());
    // Stacking-limit bonus from the improvement; zero when the stacking-rules mod flag is off.
    out.unitIncrement = static_cast<i32>(plot.getAdditionalUnitsFromImprovement());
    // Filled from the refreshed tactical analysis map.
    // zoneId has no generated assignment because its capture mode is builder.
    // Units are sorted globally by plot index then unit ID.
    // unitRange has no generated assignment because its capture mode is builder.
    // Second owner-qualified owning-city reference component.
    out.owningCityId = static_cast<i32>(plot.getOwningCity() ? plot.getOwningCity()->GetID() : -1);
    // Effective working-city owner after the native override.
    out.effectiveOwningCityOwner = static_cast<i8>(plot.getEffectiveOwningCity() ? plot.getEffectiveOwningCity()->getOwner() : NO_PLAYER);
    // Worked state used by adjacent city deep-water damage.
    out.beingWorked = (plot.isBeingWorked()) ? 1 : 0;
    // Owning player.
    out.owner = static_cast<i8>(plot.getOwner());
    // Dynamic feature type.
    out.featureType = static_cast<i8>(plot.getFeatureType());
    // Improvement pillage state.
    out.improvementPillaged = (plot.IsImprovementPillaged()) ? 1 : 0;
    // Improvement movement passability.
    out.improvementPassable = (plot.IsImprovementPassable()) ? 1 : 0;
    // Route type.
    out.routeType = static_cast<i8>(plot.getRouteType());
    // Capitalized native accessor.
    out.routePillaged = (plot.IsRoutePillaged()) ? 1 : 0;
    // Restore-moves flag.
    out.restoreMoves = (plot.IsRestoreMoves()) ? 1 : 0;
    // Free movement edge flag.
    out.freeMoveAcross = (plot.IsFreeMoveAcross()) ? 1 : 0;
    // First owner-qualified owning-city reference component; the border-obstacle rule resolves the working city.
    out.owningCityOwner = static_cast<i8>(plot.getOwningCity() ? plot.getOwningCity()->getOwner() : NO_PLAYER);
    return true;
}

