bool CollectPlotPassabilityRecord(CvPlot& plot, PlotPassabilityRecord& out)
{
    // Captured value returned for NO_TEAM.
    out.baseImpassable = (plot.isImpassable()) ? 1 : 0;
    // Captured value for every team, including the barbarian team.
    for (int index = 0; index < 64; ++index) {
        out.teamImpassable[index] = 0;
    }
    if ((MAX_TEAMS) > VoxRlTeamCapacity) {
        return false;
    }
    for (int index = 0; index < (MAX_TEAMS); ++index) {
        out.teamImpassable[index] = (plot.IsTeamImpassable(static_cast<TeamTypes>(index))) ? 1 : 0;
    }
    return true;
}

